// Simple endless arcade based on IDEA.md
(() => {
  const canvas = document.getElementById('game');
  if (!canvas) return;
  const ctx = canvas.getContext('2d');
  const WIDTH = canvas.width = 400;
  const HEIGHT = canvas.height = 600;

  // Player
  const player = { x: WIDTH / 2 - 15, y: HEIGHT - 30, w: 30, h: 30, speed: 4, dx: 0 };

  // Blocks
  const blocks = [];
  let blockTimer = 0;
  let blockInterval = 1500; // ms
  let lastTime = 0;
  let speedY = 2; // fall speed, will accelerate
  let score = 0;
  let gameOver = false;

  // Input handling
  const keys = {};
  window.addEventListener('keydown', e => { if (e.key === 'ArrowLeft' || e.key === 'a') keys.left = true; if (e.key === 'ArrowRight' || e.key === 'd') keys.right = true; });
  window.addEventListener('keyup', e => { if (e.key === 'ArrowLeft' || e.key === 'a') keys.left = false; if (e.key === 'ArrowRight' || e.key === 'd') keys.right = false; });

  function spawnBlock() {
    const w = 30 + Math.random() * 70; // 30-100px
    const x = Math.random() * (WIDTH - w);
    blocks.push({ x, y: -20, w, h: 20 });
  }

  function update(dt) {
    // player movement
    player.dx = 0;
    if (keys.left) player.dx = -player.speed;
    if (keys.right) player.dx = player.speed;
    player.x += player.dx;
    // keep within canvas
    if (player.x < 0) player.x = 0;
    if (player.x + player.w > WIDTH) player.x = WIDTH - player.w;

    // blocks
    blockTimer += dt;
    if (blockTimer > blockInterval) {
      spawnBlock();
      blockTimer = 0;
      // gradually increase difficulty
      if (blockInterval > 400) blockInterval -= 20;
      speedY += 0.02;
    }
    for (let i = blocks.length - 1; i >= 0; i--) {
      const b = blocks[i];
      b.y += speedY;
      // collision with player
      if (b.y + b.h > player.y && b.y < player.y + player.h && b.x < player.x + player.w && b.x + b.w > player.x) {
        gameOver = true;
      }
      // passed bottom
      if (b.y > HEIGHT) {
        blocks.splice(i, 1);
        score++;
      }
    }
  }

  function draw() {
    ctx.clearRect(0, 0, WIDTH, HEIGHT);
    // player
    ctx.fillStyle = '#0a84ff';
    ctx.fillRect(player.x, player.y, player.w, player.h);
    // blocks
    ctx.fillStyle = '#ff3b30';
    blocks.forEach(b => ctx.fillRect(b.x, b.y, b.w, b.h));
    // score
    ctx.fillStyle = '#000';
    ctx.font = '16px sans-serif';
    ctx.fillText('Score: ' + score, 10, 20);
    // game over
    if (gameOver) {
      ctx.fillStyle = 'rgba(0,0,0,0.6)';
      ctx.fillRect(0, 0, WIDTH, HEIGHT);
      ctx.fillStyle = '#fff';
      ctx.textAlign = 'center';
      ctx.font = '24px sans-serif';
      ctx.fillText('Game Over', WIDTH / 2, HEIGHT / 2);
    }
  }

  function loop(timestamp) {
    if (!lastTime) lastTime = timestamp;
    const dt = timestamp - lastTime;
    lastTime = timestamp;
    if (!gameOver) update(dt);
    draw();
    requestAnimationFrame(loop);
  }

  requestAnimationFrame(loop);
})();

