```javascript
// Simple endless arcade based on IDEA.md
(() => {
  const canvas = document.getElementById('game');
  if (!canvas) return;
  const ctx = canvas.getContext('2d');
  const WIDTH = canvas.width = 400;
  const HEIGHT = canvas.height = 600;

  // Player square
  const player = { x: WIDTH / 2 - 15, y: HEIGHT - 30, w: 30, h: 30, speed: 4, dx: 0 };

  // Falling blocks
  const blocks = [];
  let blockTimer = 0;
  let blockInterval = 1500; // spawn rate (ms)
  let lastTime = 0;
  let speedY = 2;          // falling speed, accelerates
  let score = 0;
  let gameOver = false;

  // Input handling
  const keys = {};
  window.addEventListener('keydown', e => {
    if (e.key === 'ArrowLeft' || e.key === 'a') keys.left = true;
    if (e.key === 'ArrowRight' || e.key === 'd') keys.right = true;
  });
  window.addEventListener('keyup', e => {
    if (e.key === 'ArrowLeft' || e.key === 'a') keys.left = false;
    if (e.key === 'ArrowRight' || e.key === 'd') keys.right = false;
  });

  function spawnBlock() {
    const w = 30 + Math.random() * 70; // width 30‑100px
    const x = Math.random() * (WIDTH - w);
    blocks.push({ x, y: -20, w, h: 20 });
  }

  function update(dt) {
    // Player movement
    player.dx = 0;
    if (keys.left) player.dx = -player.speed;
    if (keys.right) player.dx = player.speed;
    player.x = Math.max(0, Math.min(WIDTH - player.w, player.x + player.dx));

    // Spawn blocks
    blockTimer += dt;
    if (blockTimer > blockInterval) {
      spawnBlock();
      blockTimer = 0;
      if (blockInterval > 400) blockInterval -= 20; // speed up spawns
      speedY += 0.02;                               // increase fall speed
    }

    // Move blocks and check collisions
    for (let i = blocks.length - 1; i >= 0; i--) {
      const b = blocks[i];
      b.y += speedY;

      // Collision with player → game over
      if (
        b.y + b.h > player.y &&
        b.y < player.y + player.h &&
        b.x < player.x + player.w &&
        b.x + b.w > player.x
      ) {
        gameOver = true;
      }

      // Block passed the bottom → score
      if (b.y > HEIGHT) {
        blocks.splice(i, 1);
        score++;
      }
    }
  }

  function draw() {
    ctx.clearRect(0, 0, WIDTH, HEIGHT);

    // Player
    ctx.fillStyle = '#0a84ff';
    ctx.fillRect(player.x, player.y, player.w, player.h);

    // Blocks
    ctx.fillStyle = '#ff3b30';
    blocks.forEach(b => ctx.fillRect(b.x, b.y, b.w, b.h));

    // Score
    ctx.fillStyle = '#000';
    ctx.font = '16px sans-serif';
    ctx.fillText('Score: ' + score, 10, 20);

    // Game over overlay
    if (gameOver) {
      ctx.fillStyle = 'rgba(0,0,0,0.6)';
      ctx.fillRect(0, 0, WIDTH, HEIGHT);
      ctx.fillStyle = '#fff';
      ctx.textAlign = 'center';
      ctx.font = '24px sans-serif';
      ctx.fillText('Game Over', WIDTH / 2, HEIGHT / 2);
    }
  }

  function loop(timestamp) {
    if (!lastTime) lastTime = timestamp;
    const dt = timestamp - lastTime;
    lastTime = timestamp;
    if (!gameOver) update(dt);
    draw();
    requestAnimationFrame(loop);
  }

  requestAnimationFrame(loop);
})();
```

- Targets the canvas with `id="game"`.
- Implements player movement (←/→ or A/D).
- Spawns falling blocks of random widths, accelerates difficulty.
- Increments score when blocks exit the bottom.
- Ends the game on player‑block collision, showing a “Game Over” overlay.

Add `<script src="game.js"></script>` to the HTML file containing the canvas to run the game.
